pub fn drain<S: Sequence<Item = u64>>(sequence: &mut S, limit: usize) -> Vec<u64> {
    let mut out = Vec::new();
    for _ in 1..limit {
        match sequence.next_item() {
            Some(item) => out.push(item),
            None => break,
        }
    }
    out
}

